<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Ubuntu-inspired Desktop Environment</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            user-select: none;
        }

        body {
            font-family: Ubuntu, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
            overflow: hidden;
            height: 100vh;
            width: 100vw;
        }

        /* Desktop background */
        #desktop {
            position: relative;
            width: 100%;
            height: 100%;
            background: linear-gradient(135deg, #2e3440 0%, #434c5e 100%);
            overflow: hidden;
        }

        /* Taskbar */
        #taskbar {
            position: fixed;
            bottom: 0;
            left: 0;
            right: 0;
            height: 48px;
            background-color: rgba(0, 0, 0, 0.75);
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 16px;
            z-index: 100;
            border-top: 1px solid #333;
        }

        .launcher {
            width: 48px;
            height: 48px;
            display: flex;
            align-items: center;
            justify-content: center;
            background-color: transparent;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .launcher:hover {
            background-color: rgba(255, 255, 255, 0.1);
        }

        .launcher-icon {
            width: 32px;
            height: 32px;
            display: flex;
            align-items: center;
            justify-content: center;
            background-color: white;
            border-radius: 4px;
            color: #000;
        }

        /* Window styles */
        .window {
            position: absolute;
            width: 600px;
            min-width: 360px;
            height: 400px;
            min-height: 240px;
            background-color: rgba(46, 52, 64, 0.95);
            border-radius: 12px;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
            overflow: hidden;
            display: flex;
            flex-direction: column;
            z-index: 50;
            transform: scale(0.95);
            opacity: 0;
            pointer-events: none;
            transition: all 0.2s ease;
        }

        .window.active {
            transform: scale(1);
            opacity: 1;
            pointer-events: auto;
        }

        /* Window header */
        .window-header {
            background-color: #3b4252;
            height: 36px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 10px;
            cursor: grab;
        }

        .window-title {
            font-size: 14px;
            color: #fff;
        }

        .window-controls {
            display: flex;
            gap: 6px;
        }

        .win-close {
            width: 28px;
            height: 28px;
            border-radius: 50%;
            background-color: #bf6161;
            color: white;
            border: none;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
        }

        .win-close:hover {
            background-color: #d35454;
        }

        /* Window content */
        .window-content {
            flex: 1;
            overflow-y: auto;
            padding: 10px;
            color: #fff;
        }

        /* Files App Styles */
        .files-header {
            display: flex;
            align-items: center;
            margin-bottom: 15px;
            gap: 8px;
            background-color: rgba(62, 69, 82, 0.7);
            padding: 8px 12px;
            border-radius: 4px;
        }

        #files-path {
            font-size: 14px;
            color: #fff;
        }

        .fs-back-btn {
            width: 32px;
            height: 32px;
            background-color: rgba(62, 69, 82, 0.7);
            border: none;
            border-radius: 4px;
            color: #fff;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .fs-back-btn:hover {
            background-color: rgba(62, 69, 82, 0.9);
        }

        .fs-item {
            padding: 10px 15px;
            margin-bottom: 6px;
            border-radius: 4px;
            display: flex;
            align-items: center;
            gap: 10px;
            cursor: pointer;
            background-color: rgba(62, 69, 82, 0.7);
        }

        .fs-item:hover {
            background-color: rgba(62, 69, 82, 0.9);
        }

        .folder-icon,
        .file-icon {
            width: 24px;
            height: 24px;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 3px;
        }

        .folder-icon {
            background-color: #bf9a5e;
        }

        .file-icon {
            background-color: #7d8aa6;
        }

        /* Notepad App Styles */
        .notepad-container {
            height: 100%;
            display: flex;
            flex-direction: column;
        }

        #tabs {
            display: flex;
            background-color: #3b4252;
            border-bottom: 1px solid #3b4252;
        }

        .tab {
            padding: 8px 16px;
            cursor: pointer;
            color: #d8dee9;
            border-right: 1px solid #3b4252;
            position: relative;
            font-size: 14px;
            transition: all 0.2s ease;
        }

        .tab.active {
            background-color: #4c566a;
            color: #fff;
            border-top: 2px solid #88c0d0;
            margin-bottom: -1px;
        }

        .tab:hover:not(.active) {
            background-color: rgba(255, 255, 255, 0.05);
        }

        #new-tab {
            padding: 8px 16px;
            cursor: pointer;
            color: #d8dee9;
            display: flex;
            align-items: center;
        }

        #editor-container {
            flex: 1;
            overflow: auto;
            position: relative;
        }

        #editor {
            width: 100%;
            height: 100%;
            background-color: rgba(46, 52, 64, 0.95);
            color: #d8dee9;
            border: none;
            resize: none;
            padding: 15px;
            font-family: monospace;
            font-size: 14px;
            outline: none;
        }

        /* Placeholder text */
        .empty-placeholder {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            color: #88c0d0;
            font-style: italic;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="desktop">
        <!-- Taskbar -->
        <div id="taskbar">
            <button class="launcher" id="open-files">
                <div class="launcher-icon">📁</div>
            </button>
            <button class="launcher" id="open-notepad">
                <div class="launcher-icon">📝</div>
            </button>
        </div>

        <!-- Files App Window -->
        <div id="files-window" class="window">
            <div class="window-header" style="cursor: default;">
                <span class="window-title">Files</span>
                <div class="window-controls">
                    <button class="win-close">×</button>
                </div>
            </div>
            <div class="window-content">
                <div class="files-header">
                    <button id="files-up" class="fs-back-btn">⬆️</button>
                    <span id="files-path">/</span>
                </div>
                <div id="files-list"></div>
            </div>
        </div>

        <!-- Notepad App Window -->
        <div id="notepad-window" class="window">
            <div class="window-header" style="cursor: default;">
                <span class="window-title">Notepad</span>
                <div class="window-controls">
                    <button class="win-close">×</button>
                </div>
            </div>
            <div class="notepad-container window-content">
                <div id="tabs"></div>
                <div id="editor-container">
                    <div id="empty-msg" class="empty-placeholder">Start typing here...</div>
                    <textarea id="editor" placeholder="Start typing here..."></textarea>
                </div>
            </div>
        </div>
    </div>

    <script>
        // ==================== File System Data ====================
        const fileSystem = {
            "/": {
                "bin": { type: "folder", content: {} },
                "etc": { type: "folder", content: {} },
                "home": { type: "folder", content: {
                    "user": { type: "folder", content: {
                        "Documents": { type: "folder", content: {} },
                        "Downloads": { type: "folder", content: {} },
                        "Pictures": { type: "folder", content: {} }
                    }}
                }},
                "usr": { type: "folder", content: {} },
                "var": { type: "folder", content: {} }
            }
        };

        // ==================== Files App Logic ====================
        const filesWindow = document.getElementById('files-window');
        const filesPathDisplay = document.getElementById('files-path');
        const filesList = document.getElementById('files-list');
        const filesUpButton = document.getElementById('files-up');

        let currentPath = "/";
        let fileSystemState = JSON.parse(JSON.stringify(fileSystem));

        // Function to get a nested object from path
        function getObjectFromPath(path) {
            if (path === "/") return fileSystemState;
            const parts = path.split('/').filter(p => p);
            let obj = fileSystemState;
            for (const part of parts) {
                if (obj.content && obj.content[part]) {
                    obj = obj.content[part];
                } else {
                    return null;
                }
            }
            return obj;
        }

        // Function to render files list
        function renderFiles() {
            const currentObj = getObjectFromPath(currentPath);
            filesList.innerHTML = '';

            if (!currentObj) return;

            // Get entries sorted (folders first, then alphabetically)
            const entries = Object.entries(currentObj.content || {});

            // Sort folders first, then by name
            entries.sort((a, b) => {
                if (a[1].type === 'folder' && b[1].type !== 'folder') return -1;
                if (a[1].type !== 'folder' && b[1].type === 'folder') return 1;
                return a[0].localeCompare(b[0]);
            });

            for (const [name, info] of entries) {
                const item = document.createElement('div');
                item.className = 'fs-item';
                item.dataset.name = name;

                // Add icon based on type
                if (info.type === 'folder') {
                    const folderIcon = document.createElement('div');
                    folderIcon.className = 'folder-icon';
                    folderIcon.textContent = '📁';
                    item.appendChild(folderIcon);

                    // Double-click to navigate into the folder
                    item.addEventListener('dblclick', () => {
                        navigateToPath(currentPath === "/" ? "/" + name : currentPath + "/" + name);
                    });
                } else {
                    const fileIcon = document.createElement('div');
                    fileIcon.className = 'file-icon';
                    fileIcon.textContent = '📄';
                    item.appendChild(fileIcon);
                }

                // Add name text
                const nameSpan = document.createElement('span');
                nameSpan.textContent = name;
                item.appendChild(nameSpan);

                filesList.appendChild(item);
            }
        }

        // Function to navigate to path
        function navigateToPath(path) {
            currentPath = path;

            // Validate the path exists
            if (getObjectFromPath(currentPath)) {
                updateFilesUI();
            } else {
                alert("Invalid path: " + path);
            }
        }

        // Function to handle parent directory navigation
        filesUpButton.addEventListener('click', () => {
            if (currentPath === "/") return;

            const parts = currentPath.split('/').filter(p => p);
            parts.pop();
            navigateToPath(parts.length > 0 ? '/' + parts.join('/') : '/');
        });

        // Update UI elements for files app
        function updateFilesUI() {
            filesPathDisplay.textContent = currentPath || "/";
            renderFiles();
        }

        // ==================== Notepad App Logic ====================
        const notepadWindow = document.getElementById('notepad-window');
        const tabsContainer = document.getElementById('tabs');
        const editor = document.getElementById('editor');
        const newTabButton = document.getElementById('new-tab');
        const emptyMsg = document.getElementById('empty-msg');

        let tabs = [];
        let activeTabId = null;

        // Initialize with localStorage
        function initNotepad() {
            const savedTabs = JSON.parse(localStorage.getItem('ubuntu-notepad-tabs')) || [];

            if (savedTabs.length > 0) {
                tabs = savedTabs;
                activeTabId = tabs[0].id;
            } else {
                addNewTab();
            }

            renderTabs();
        }

        // Save current state to localStorage
        function saveNotepadState() {
            localStorage.setItem('ubuntu-notepad-tabs', JSON.stringify(tabs));
        }

        // Add a new tab
        function addNewTab() {
            const id = Date.now().toString() + Math.random().toString(36).substr(2, 9);
            tabs.push({
                id: id,
                title: `Tab ${tabs.length + 1}`,
                content: ""
            });

            activeTabId = id;
            renderTabs();
            saveNotepadState();
        }

        // Remove a tab
        function removeTab(id) {
            if (tabs.length <= 1) return; // Keep at least one tab

            const index = tabs.findIndex(tab => tab.id === id);
            if (index === -1) return;

            const isActive = id === activeTabId;

            tabs.splice(index, 1);

            if (isActive) {
                activeTabId = tabs[Math.max(0, index - 1)].id;
            }

            renderTabs();
            saveNotepadState();
        }

        // Switch to a tab
        function switchTab(id) {
            activeTabId = id;
            renderTabs();
        }

        // Get current active tab content
        function getActiveTab() {
            return tabs.find(tab => tab.id === activeTabId);
        }

        // Render all tabs
        function renderTabs() {
            tabsContainer.innerHTML = '';

            for (const tab of tabs) {
                const tabElement = document.createElement('div');
                tabElement.className = `tab ${tab.id === activeTabId ? 'active' : ''}`;
                tabElement.textContent = tab.title;

                // Switch to this tab on click
                tabElement.addEventListener('click', () => {
                    switchTab(tab.id);
                    editor.focus();
                });

                tabsContainer.appendChild(tabElement);
            }

            // Add new tab button
            const newTabEl = document.createElement('div');
            newTabEl.id = 'new-tab';
            newTabEl.textContent = '+';
            newTabEl.addEventListener('click', (e) => {
                e.stopPropagation();
                addNewTab();
            });
            tabsContainer.appendChild(newTabEl);

            // Show/hide empty message and update editor content
            const activeTab = getActiveTab();
            if (activeTab && activeTab.content === "") {
                emptyMsg.style.display = 'block';
            } else {
                emptyMsg.style.display = 'none';
            }

            if (activeTab) {
                editor.value = activeTab.content;
            }
        }

        // Listen for editor input
        editor.addEventListener('input', () => {
            const activeTab = getActiveTab();
            if (activeTab) {
                activeTab.content = editor.value;
                saveNotepadState();

                if (editor.value === "") {
                    emptyMsg.style.display = 'block';
                } else {
                    emptyMsg.style.display = 'none';
                }
            }
        });

        // ==================== Window Management Logic ====================

        // Helper to open a window
        function openWindow(windowId) {
            const win = document.getElementById(windowId);
            if (win) {
                // Deactivate other windows
                document.querySelectorAll('.window').forEach(w => {
                    if (w !== win) w.classList.remove('active');
                });

                // Activate this window
                win.classList.add('active');

                // If it's the files window, update its state
                if (windowId === 'files-window') {
                    updateFilesUI();
                }
            }
        }

        // Helper to close a window
        function closeWindow(windowId) {
            const win = document.getElementById(windowId);
            if (win) {
                win.classList.remove('active');

                // Add animation delay before removing from view completely
                setTimeout(() => {
                    win.style.display = 'none';
                    // If it's not visible, we don't remove from DOM, just hide
                }, 200);
            }
        }

        // ==================== Event Listeners for Launchers ====================

        document.getElementById('open-files').addEventListener('click', (e) => {
            e.stopPropagation();
            openWindow('files-window');
        });

        document.getElementById('open-notepad').addEventListener('click', (e) => {
            e.stopPropagation();
            if (!notepadWindow.classList.contains('active')) {
                notepadWindow.style.display = 'flex';
                initNotepad();
                openWindow('notepad-window');
            } else {
                closeWindow('notepad-window');
            }
        });

        // ==================== Window Close Buttons ====================

        document.querySelectorAll('.win-close').forEach(closeBtn => {
            closeBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                const win = closeBtn.closest('.window');
                if (win) {
                    closeWindow(win.id);
                }
            });
        });

        // Close window when clicking outside
        document.getElementById('desktop').addEventListener('click', () => {
            // Don't do anything - we want to keep focus on active windows
        });

        // ==================== Window Dragging Logic ====================

        let draggedWindow = null;
        let dragOffsetX = 0;
        let dragOffsetY = 0;

        document.querySelectorAll('.window-header').forEach(header => {
            header.addEventListener('mousedown', (e) => {
                if (e.target.closest('.win-close') || e.target.closest('.tab')) return;

                const windowEl = header.closest('.window');
                if (!windowEl.classList.contains('active')) {
                    // Activate the window first
                    document.querySelectorAll('.window').forEach(w => w.classList.remove('active'));
                    windowEl.classList.add('active');
                }

                draggedWindow = windowEl;

                // Calculate offset for dragging
                const rect = windowEl.getBoundingClientRect();
                dragOffsetX = e.clientX - rect.left;
                dragOffsetY = e.clientY - rect.top;

                document.body.style.cursor = 'grabbing';
            });
        });

        document.addEventListener('mousemove', (e) => {
            if (!draggedWindow || draggedWindow.style.display === 'none') return;

            // Calculate new position
            const desktopRect = document.getElementById('desktop').getBoundingClientRect();

            let newX = e.clientX - desktopRect.left - dragOffsetX;
            let newY = e.clientY - desktopRect.top - dragOffsetY;

            // Constrain to window boundaries (simple constraint)
            const winWidth = draggedWindow.offsetWidth;
            const winHeight = draggedWindow.offsetHeight;

            if (newX < 0) newX = 0;
            if (newY < 0) newY = 0;
            if (newX + winWidth > desktopRect.width - 20) newX = desktopRect.width - winWidth - 20;
            if (newY + winHeight > desktopRect.height - 60) newY = desktopRect.height - winHeight - 60;

            draggedWindow.style.left = `${newX}px`;
            draggedWindow.style.top = `${newY}px`;
        });

        document.addEventListener('mouseup', () => {
            if (draggedWindow) {
                draggedWindow.style.cursor = 'default';
                draggedWindow = null;
                document.body.style.cursor = 'default';

                // Update position for persistence
                const winId = draggedWindow ? draggedWindow.id : '';
                if (winId && !isNaN(parseInt(winId.split('-')[0]))) return; // Not a window we track

                if (draggedWindow) {
                    draggedWindow.dataset.lastX = draggedWindow.style.left;
                    draggedWindow.dataset.lastY = draggedWindow.style.top;
                }
            }
        });

        // ==================== Initialize Files App ====================
        function initFilesApp() {
            // Add event listeners for initial setup
            renderFiles();

            // If no window is active, we'll wait for user to click a launcher
        }

        // Wait for DOM to load before initializing
        document.addEventListener('DOMContentLoaded', () => {
            initFilesApp();
            initNotepad();
        });

        // ==================== Files Up Button Event (redundant safety) ====================
        filesUpButton.addEventListener('click', (e) => {
            e.stopPropagation();
            if (currentPath !== "/") {
                const parts = currentPath.split('/').filter(p => p);
                parts.pop();
                navigateToPath(parts.length > 0 ? '/' + parts.join('/') : '/');
            }
        });
    </script>
</body>
</html>
